mkdir -p /out; cat > /tmp/c.py <<'EOF'
import json
rows=[];errs=[]
data=open('/data/events.jsonl',encoding='utf-8').read().split('\n')
if data and data[-1]=='': data.pop()
def flat(o,p,out):
    for k,v in o.items():
        key=p+k
        if isinstance(v,dict): flat(v,key+'.',out)
        else: out[key]=v
for i,l in enumerate(data,1):
    if l.strip()=='': continue
    try: o=json.loads(l)
    except Exception: errs.append(i); continue
    if not isinstance(o,dict): errs.append(i); continue
    d={}; flat(o,'',d); rows.append(d)
cols=sorted({k for r in rows for k in r})
def cell(v):
    if v is None: return ''
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v,str): return v
    if isinstance(v,list): return json.dumps(v,separators=(',',':'),ensure_ascii=False)
    return json.dumps(v)
def q(s):
    return '"'+s.replace('"','""')+'"' if any(c in s for c in ',"\n') else s
with open('/out/events.csv','w',encoding='utf-8',newline='') as f:
    f.write(','.join(map(q,cols))+'\n')
    for r in rows: f.write(','.join(q(cell(r.get(c))) for c in cols)+'\n')
with open('/out/errors.txt','w',newline='') as f:
    f.write(''.join(f'line {n}\n' for n in errs))
EOF
python3 /tmp/c.py; cat /out/events.csv; cat /out/errors.txt

